<?php
declare(strict_types=1);

function mcpFollowUpActionAvailable(array $action): bool {
  foreach($action['permissionClasses']??array() as $class){
    if(!SqlElement::class_exists((string)$class))return false;
    $policy=mcpClassPolicy((string)$class);if(!($policy['supported']??false))return false;
    try{
      if(Security::checkValidAccessForUser(null,'read',(string)$class,null,false))continue;
      if(in_array('create',$policy['operations']??array(),true)&&Security::checkValidAccessForUser(new $class(),'create',null,null,false))continue;
    }catch(Throwable $error){}
    return false;
  }
  return true;
}
function mcpFollowUpDirectAccess(object $object,string $operation): bool { try{return (bool)Security::checkValidAccessForUser($object,$operation,null,null,false);}catch(Throwable $error){return false;} }
function mcpFollowUpTarget(string $class,int $id,string $operation='read'): object { Security::checkValidClass($class);$object=new $class($id);if(!$object->id)mcpJsonError(404,'follow_up_target_not_found',"$class #$id was not found");if(!mcpFollowUpDirectAccess($object,$operation))mcpJsonError(403,'forbidden',"$operation access is denied for $class #$id");return $object; }
function mcpFollowUpRequireVersion(object $object,?string $expected): void { if(!$object->id)return;if($expected===null||$expected==='')mcpJsonError(409,'expected_version_required',get_class($object).' #'.$object->id.' requires expectedVersion');$actual=mcpObjectVersion($object);if(!hash_equals($actual,$expected))mcpJsonError(409,'version_conflict',get_class($object).' #'.$object->id.' has changed',array('expectedVersion'=>$expected,'actualVersion'=>$actual)); }
