function mcpFollowUpFields(array $source,array $allowed): array { $result=array();foreach($allowed as $field)if(array_key_exists($field,$source))$result[$field]=$source[$field];return $result; }
function mcpFollowUpSaved(object $object): array { return array('id'=>(int)$object->id,'_version'=>mcpObjectVersion($object)); }
function mcpFollowUpItem(string $status,string $class,?int $id,array $requested=array(),array $applied=array(),array $recalculated=array(),array $saved=array(),array $related=array()): array { return array('status'=>$status,'objectClass'=>$class,'id'=>$id,'relatedIds'=>array_values(array_unique(array_filter(array_map('intval',$related)))),'requestedFields'=>$requested,'appliedFields'=>$applied,'recalculatedFields'=>$recalculated,'ignoredFields'=>array(),'rejectedFields'=>array(),'saved'=>$saved,'concurrencyUnchecked'=>false); }
function mcpFollowUpEffects(array $items): array { $effects=array();foreach($items as $item){$status=(string)($item['status']??'');if(in_array($status,array('error','rolled_back'),true))continue;$action=$status==='deleted'?'delete':(in_array($status,array('created'),true)?'create':'update');if(!empty($item['id']))$effects[]=array('action'=>$action,'objectClass'=>$item['objectClass']??null,'id'=>(int)$item['id']);foreach($item['relatedIds']??array() as $id)$effects[]=array('action'=>'update','objectClass'=>null,'id'=>(int)$id);}return $effects; }
function mcpFollowUpBatch(array $entries,string $mode,callable $executor): array {
  if(count($entries)<1||count($entries)>200)mcpJsonError(400,'invalid_batch','Follow-up actions require 1 to 200 items');if(!in_array($mode,array('atomic','best_effort'),true))mcpJsonError(400,'invalid_transaction_mode','transactionMode must be atomic or best_effort');
  $items=array();$previousCapture=$GLOBALS['mcpCaptureErrors']??false;if($mode==='atomic')Sql::beginTransaction();
  foreach($entries as $index=>$entry){if($mode==='best_effort')Sql::beginTransaction();$GLOBALS['mcpCaptureErrors']=true;try{$item=$executor($entry,$index);$item['index']=$index;$items[]=$item;if($mode==='best_effort')Sql::commitTransaction();}catch(Throwable $error){
    if($mode==='best_effort')Sql::rollbackTransaction();$details=$error instanceof McpBridgeException?array_merge(array('code'=>$error->errorCode,'message'=>cleanApiMessage($error->getMessage())),$error->details):array('code'=>'follow_up_operation_failed','message'=>cleanApiMessage($error->getMessage()));$details=mcpFollowUpFields($details,array('code','message','objectClass','id','expectedVersion','actualVersion','missingFields','invalidFields','workTotal','detailTotal'));
    $items[]=array('index'=>$index,'status'=>'error','objectClass'=>'FollowUp','id'=>$entry['id']??null,'error'=>$details);
    if($mode==='atomic'){Sql::rollbackTransaction();foreach($items as &$rolledBack)if(($rolledBack['status']??'')!=='error'){$rolledBack['status']='rolled_back';$rolledBack['rejectedFields']=array_values(array_unique(array_merge($rolledBack['rejectedFields']??array(),$rolledBack['appliedFields']??array())));$rolledBack['appliedFields']=array();$rolledBack['recalculatedFields']=array();$rolledBack['saved']=array();}unset($rolledBack);return array('ok'=>false,'rolledBack'=>true,'transactionMode'=>$mode,'items'=>$items,'effects'=>array());}
  }finally{$GLOBALS['mcpCaptureErrors']=$previousCapture;}}
  if($mode==='atomic')Sql::commitTransaction();return array('ok'=>!count(array_filter($items,fn($item)=>($item['status']??'')==='error')),'rolledBack'=>false,'transactionMode'=>$mode,'items'=>$items,'effects'=>mcpFollowUpEffects($items));
}
function mcpFollowUpDate(string $date): void { $value=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$value||$value->format('Y-m-d')!==$date)mcpJsonError(400,'invalid_date',"Invalid work date '$date'"); }
function mcpFollowUpWorkContext(array $entry): array { $resourceId=(int)$entry['resourceId'];$assignment=null;$workElement=null;$refType=(string)($entry['refType']??'');$refId=(int)($entry['refId']??0);if(!empty($entry['assignmentId'])){$assignment=new Assignment((int)$entry['assignmentId']);if(!$assignment->id||((int)$assignment->idResource!==$resourceId&&!$assignment->isResourceTeam))mcpJsonError(400,'assignment_mismatch','Assignment is unavailable or belongs to another resource');$refType=(string)$assignment->refType;$refId=(int)$assignment->refId;}elseif(!empty($entry['workElementId'])){$workElement=new WorkElement((int)$entry['workElementId']);if(!$workElement->id)mcpJsonError(404,'work_element_not_found','Work element was not found');$refType=(string)$workElement->refType;$refId=(int)$workElement->refId;}elseif($refType!==''&&$refId>0){$rows=(new Assignment())->getSqlElementsFromCriteria(array('refType'=>$refType,'refId'=>$refId,'idResource'=>$resourceId),false,null,'id desc');if($rows)$assignment=reset($rows);else{$workElement=SqlElement::getSingleSqlElementFromCriteria('WorkElement',array('refType'=>$refType,'refId'=>$refId));}}else mcpJsonError(400,'missing_work_target','assignmentId, workElementId, or refType/refId is required');$target=mcpFollowUpTarget($refType,$refId,'read');return array($assignment,$workElement,$target,$refType,$refId); }
function mcpFollowUpFindWork(array $entry,?Assignment $assignment,?WorkElement $workElement,string $refType,int $refId): Work { if(!empty($entry['id'])){$work=new Work((int)$entry['id']);if(!$work->id)mcpJsonError(404,'work_not_found','Work entry was not found');}else{$criteria=array('idResource'=>(int)$entry['resourceId'],'workDate'=>(string)$entry['workDate']);if($assignment&&$assignment->id)$criteria['idAssignment']=(int)$assignment->id;elseif($workElement&&$workElement->id)$criteria['idWorkElement']=(int)$workElement->id;else{$criteria['refType']=$refType;$criteria['refId']=$refId;}$work=SqlElement::getSingleSqlElementFromCriteria('Work',$criteria);}if($work->id&&((int)$work->idResource!==(int)$entry['resourceId']||(string)$work->refType!==$refType||(int)$work->refId!==$refId))mcpJsonError(400,'work_target_mismatch','Existing work does not belong to the requested resource and target');return $work; }
