function mcpFollowUpWorkRecordAction(array $arguments,string $username,string $action): array { return mcpFollowUpBatch($arguments['entries'],(string)($arguments['transactionMode']??'atomic'),fn(array $entry)=>mcpFollowUpWorkRecordOne($entry)); }
function mcpFollowUpWorkRecordOne(array $entry): array {
  $resourceId=(int)$entry['resourceId'];$date=(string)$entry['workDate'];mcpFollowUpDate($date);mcpFollowUpRequireResource($resourceId);if((float)$entry['work']<=0)mcpJsonError(400,'zero_work_requires_delete','Use follow_up.work.delete to remove an existing work entry');list($assignment,$workElement,$target,$refType,$refId)=mcpFollowUpWorkContext($entry);$work=mcpFollowUpFindWork($entry,$assignment,$workElement,$refType,$refId);
  $operation=(string)($entry['operation']??'upsert');if($operation==='create'&&$work->id)mcpJsonError(409,'work_exists','A work entry already exists for this target and date');if($operation==='update'&&!$work->id)mcpJsonError(404,'work_not_found','Work entry was not found');$wasNew=!$work->id;if(!$wasNew)mcpFollowUpRequireVersion($work,$entry['expectedVersion']??null);mcpRequireClassOperation('Work',$wasNew?'create':'update');
