  if($assignment&&$assignment->id){$work->updateAssignment((float)$work->work-$oldWork);$assignment=new Assignment((int)$assignment->id);if(array_key_exists('leftWork',$entry))$assignment->leftWork=(float)$entry['leftWork'];if(array_key_exists('comment',$entry))$assignment->comment=(string)$entry['comment'];if(array_key_exists('leftWork',$entry)||array_key_exists('comment',$entry)){$saved=$assignment->saveWithRefresh();if(!in_array(getLastOperationStatus($saved),array('OK','NO_CHANGE'),true))mcpJsonError(400,'assignment_save_failed',cleanApiMessage($saved));}$related[]=(int)$assignment->id;$recalculated[]=array_key_exists('leftWork',$entry)?'assignment.leftWork':'assignment.realWork';}
