function mcpFollowUpPeriodSubmitAction(array $arguments,string $username,string $action): array { $operation=(string)$arguments['operation'];return mcpFollowUpBatch($arguments['periods'],(string)($arguments['transactionMode']??'atomic'),function(array $entry)use($operation):array{mcpFollowUpRequireResource((int)$entry['resourceId']);$period=mcpFollowUpPeriod($entry,$operation==='unsubmit');mcpRequireClassOperation('WorkPeriod',$period->id?'update':'create');$period->submitted=$operation==='submit'?1:0;$period->submittedDate=$operation==='submit'?date('Y-m-d H:i:s'):null;if(array_key_exists('comment',$entry))$period->comment=$entry['comment'];$raw=$period->save();if(!in_array(getLastOperationStatus($raw),array('OK','NO_CHANGE'),true))mcpJsonError(400,'work_period_save_failed',cleanApiMessage($raw));return mcpFollowUpItem($operation==='submit'?'submitted':'unsubmitted','WorkPeriod',(int)$period->id,array('submitted','submittedDate','comment'),array('submitted','submittedDate','comment'),array(),mcpFollowUpSaved(new WorkPeriod($period->id)));}); }
function mcpFollowUpPeriodValidationAction(array $arguments,string $username,string $action): array { $decision=(string)$arguments['decision'];return mcpFollowUpBatch($arguments['periods'],(string)($arguments['transactionMode']??'atomic'),function(array $entry)use($decision):array{mcpFollowUpRequireResource((int)$entry['resourceId'],true);$period=mcpFollowUpPeriod($entry,true);mcpRequireClassOperation('WorkPeriod','update');if($decision==='validate'){$period->validated=1;$period->validatedDate=date('Y-m-d H:i:s');$period->idLocker=(int)getSessionUser()->id;$status='validated';}elseif($decision==='reject'){$period->submitted=0;$period->submittedDate=null;$period->validated=0;$period->validatedDate=null;$period->idLocker=null;$status='rejected';}else{$period->validated=0;$period->validatedDate=null;$period->idLocker=null;$status='cancelled';}if(array_key_exists('comment',$entry))$period->comment=$entry['comment'];$raw=$period->save();if(!in_array(getLastOperationStatus($raw),array('OK','NO_CHANGE'),true))mcpJsonError(400,'work_period_save_failed',cleanApiMessage($raw));return mcpFollowUpItem($status,'WorkPeriod',(int)$period->id,array('decision','comment'),array('submitted','validated','submittedDate','validatedDate','idLocker','comment'),array(),mcpFollowUpSaved(new WorkPeriod($period->id)));}); }
function mcpFollowUpRequireAlertAdmin(): void { if(securityGetAccessRightYesNo('menuAdmin','read')!=='YES')mcpJsonError(403,'forbidden','Administration access is required to generate imputation alerts'); }
function mcpFollowUpAlertPreview(array $arguments,string $username,string $action): array { mcpFollowUpRequireAlertAdmin();mcpFollowUpDate((string)$arguments['startDate']);mcpFollowUpDate((string)$arguments['endDate']);if($arguments['endDate']<$arguments['startDate'])mcpJsonError(400,'invalid_date_range','endDate must not be earlier than startDate');$deliveries=array('resource'=>$arguments['resourceDelivery']??'NO','projectLeader'=>$arguments['projectLeaderDelivery']??'NO','teamManager'=>$arguments['teamManagerDelivery']??'NO','organizationManager'=>$arguments['organizationManagerDelivery']??'NO');if(!count(array_filter($deliveries,fn($value)=>$value!=='NO')))mcpJsonError(400,'no_delivery_selected','At least one alert delivery must be enabled');return array('startDate'=>$arguments['startDate'],'endDate'=>$arguments['endDate'],'deliveries'=>$deliveries,'mayCreateAlerts'=>(bool)count(array_filter($deliveries,fn($value)=>str_contains($value,'ALERT'))),'maySendMail'=>(bool)count(array_filter($deliveries,fn($value)=>str_contains($value,'MAIL')))); }
function mcpFollowUpCommentAction(array $arguments,string $username,string $action): array { return mcpFollowUpBatch(array($arguments),'atomic',function(array $entry):array{$assignment=new Assignment((int)$entry['assignmentId']);if(!$assignment->id)mcpJsonError(404,'assignment_not_found','Assignment was not found');$target=mcpFollowUpTarget((string)$assignment->refType,(int)$assignment->refId,'update');mcpFollowUpRequireVersion($assignment,(string)$entry['expectedVersion']);mcpRequireClassOperation('Assignment','update');$stamp='['.date('Y-m-d H:i:s').']: '.(string)$entry['comment'];$assignment->comment=$stamp."\n\n".(string)$assignment->comment;$raw=$assignment->save();if(getLastOperationStatus($raw)!=='OK')mcpJsonError(400,'assignment_save_failed',cleanApiMessage($raw));$related=array();if(!empty($entry['saveAsNote'])){mcpRequireClassOperation('Note','create');$note=new Note();$note->idUser=(int)getSessionUser()->id;$note->creationDate=date('Y-m-d H:i:s');$note->refType=(string)$assignment->refType;$note->refId=(int)$assignment->refId;$note->note=nl2brForPlainText($stamp);$note->idPrivacy=1;if(!mcpFollowUpDirectAccess($note,'create'))mcpJsonError(403,'forbidden','Note creation is denied');$raw=$note->save();if(getLastOperationStatus($raw)!=='OK')mcpJsonError(400,'note_save_failed',cleanApiMessage($raw));$related[]=(int)$note->id;}return mcpFollowUpItem('updated','Assignment',(int)$assignment->id,array('comment','saveAsNote'),array('comment'),array(),mcpFollowUpSaved(new Assignment($assignment->id)),$related);}); }
function mcpFollowUpTimesheetResultAction(array $arguments,string $username,string $action): array { return mcpFollowUpBatch(array($arguments),'atomic',function(array $entry):array{$activity=mcpFollowUpTarget('Activity',(int)$entry['activityId'],'update');mcpFollowUpRequireVersion($activity,(string)$entry['expectedVersion']);mcpRequireClassOperation('Activity','update');$activity->result=$entry['result'];$raw=$activity->save();if(getLastOperationStatus($raw)!=='OK')mcpJsonError(400,'activity_save_failed',cleanApiMessage($raw));return mcpFollowUpItem('updated','Activity',(int)$activity->id,array('result'),array('result'),array(),mcpFollowUpSaved(new Activity($activity->id)));}); }
